static double rf_read_double(const double* p) {
  double v;
  memcpy_P(&v, p, sizeof(double));
  return v;
}

static int rf_read_i16(const int16_t* p) {
  int16_t v;
  memcpy_P(&v, p, sizeof(int16_t));
  return (int)v;
}

static int rf_read_i8(const int8_t* p) {
  int8_t v;
  memcpy_P(&v, p, sizeof(int8_t));
  return (int)v;
}

static uint16_t rf_read_u16(const uint16_t* p) {
  uint16_t v;
  memcpy_P(&v, p, sizeof(uint16_t));
  return v;
}

static void rf_predict_proba(const double x[11], double outProba[4]) {
  for (int c = 0; c < 4; ++c) outProba[c] = 0.0;

  for (uint16_t t = 0; t < RF_N_TREES; ++t) {
    uint16_t base = rf_read_u16(&RF_TREE_OFFSETS[t]);
    uint16_t node = 0;

    while (true) {
      int feature = rf_read_i8(&RF_FEATURE[base + node]);

      // sklearn marks leaf nodes with feature = -2.
      if (feature <= -2) {
        uint32_t valueBase = ((uint32_t)base + node) * 4UL;
        double total = 0.0;
        for (int c = 0; c < 4; ++c)
          total += (double)rf_read_u16(&RF_VALUE[valueBase + c]);

        if (total > 0.0) {
          for (int c = 0; c < 4; ++c)
            outProba[c] += (double)rf_read_u16(&RF_VALUE[valueBase + c]) / total;
        }
        break;
      }

      double threshold = rf_read_double(&RF_THRESHOLD[base + node]);
      int16_t l = (int16_t)rf_read_i16(&RF_LEFT[base + node]);
      int16_t r = (int16_t)rf_read_i16(&RF_RIGHT[base + node]);

      if (x[feature] <= threshold) node = (uint16_t)l;
      else node = (uint16_t)r;
    }
  }

  for (int c = 0; c < 4; ++c)
    outProba[c] /= (double)RF_N_TREES;
}

static uint8_t rf_predict(const double x[11], double outProba[4]) {
  rf_predict_proba(x, outProba);
  uint8_t best = 0;
  for (uint8_t c = 1; c < 4; ++c) {
    if (outProba[c] > outProba[best]) best = c;
  }
  return best;
}
